echo "=== ~/.claude/settings.json — hook commands (USER-GLOBAL, always trusted by Grok) ===" && python3 <<'PY'
import json, os
for p in [os.path.expanduser("~/.claude/settings.json"), os.path.expanduser("~/.claude/settings.local.json")]:
    if not os.path.exists(p):
        print(f"{p}: (absent)"); continue
    print(f"\n--- {p} ---")
    try: d = json.load(open(p))
    except Exception as e: print("  unparseable:", e); continue
    hooks = d.get("hooks", {})
    n = 0
    for event, groups in hooks.items():
        for g in groups:
            m = g.get("matcher", "")
            for h in g.get("hooks", []):
                n += 1
                cmd = str(h.get("command", ""))[:100]
                print(f"  {event:20} matcher={m!r:26} {cmd}")
    print(f"  TOTAL: {n} hooks")
PY

